static void رویداد(int مالک_شئ,int مقدار){if(항목수[مالک_شئ]<16){رویداد_لیست[مالک_شئ][(첫항목[مالک_شئ]+항목수[مالک_شئ])%16]=مقدار;항목수[مالک_شئ]++;}}
