static void مرتب_کردن(int مالک_شئ,ویجت_وضعیت *너비값,int *مختصات_x,int *دکمه_Y_مختصات){*مختصات_x=너비값->مختصات_x;*دکمه_Y_مختصات=너비값->دکمه_Y_مختصات;int داده_ها_مرتب_کردن=너비값->부모항목;for(int 개수=0;داده_ها_مرتب_کردن&&개수<32;개수++){ویجت_وضعیت *위쪽=عنصر_مقدار(مالک_شئ,داده_ها_مرتب_کردن);if(!위쪽)break;*مختصات_x+=위쪽->مختصات_x;*دکمه_Y_مختصات+=위쪽->دکمه_Y_مختصات+(위쪽->دسته_مقدار==1?30:0);داده_ها_مرتب_کردن=위쪽->부모항목;}}
static int 표시됨(int مالک_شئ,ویجت_وضعیت *너비값){for(int 개수=0;개수<32;개수++){if(!너비값->보이는지)return 0;if(너비값->دسته_مقدار==1)return 1;너비값=عنصر_مقدار(مالک_شئ,너비값->부모항목);if(!너비값)return 0;}return 0;}
