        ویجت_وضعیت *너비값=&요소들[مالک_شئ][순번];if(너비값->دسته_مقدار!=처리차례||!표시됨(مالک_شئ,너비값))continue;int مختصات_x,دکمه_Y_مختصات;مرتب_کردن(مالک_شئ,너비값,&مختصات_x,&دکمه_Y_مختصات);
