        if(مختصات_x<پنجره_دکمه_X||دکمه_Y_مختصات<پنجره_دکمه_Y||مختصات_x>=پنجره_دکمه_X+너비값->너비값||دکمه_Y_مختصات>=پنجره_دکمه_Y+너비값->높이값)continue;
