int 화면글(int مالک_شئ,int شناسه_مقدار,const uint32_t *داده_ها,unsigned 개수){ویجت_وضعیت *너비값=عنصر_مقدار(مالک_شئ,شناسه_مقدار);if(!너비값)return -9;if(개수>127)return -22;for(unsigned 순번=0;순번<개수;순번++){unsigned نویسه_رمزگذاری=داده_ها[순번];if(نویسه_رمزگذاری>0x10ffff||(نویسه_رمزگذاری>=0xd800&&نویسه_رمزگذاری<=0xdfff))return -22;}for(unsigned 순번=0;순번<개수;순번++)너비값->متن[순번]=داده_ها[순번];너비값->طول_مقدار=개수;if(표시됨(مالک_شئ,너비값))تخته_ای_پایانه(3);return 0;}
